AGEMsg=function(){this.spmsgerr="spmsgerr";this.diverrmsg="diverrmsg"};AGEMsg.prototype.Show=function(n,t){$("spmsgerr").className=t?"msgscc":"msgerr";$(this.spmsgerr).innerHTML=n;document.getElementById("spmsgerr").childNodes[0].tagName=="TABLE"&&document.getElementById("spmsgerr").classList.add("container");$(this.diverrmsg).style.display=IE?"block":"table"};AGEMsg.prototype.ShowMsgs=function(n,t){$("spmsgerr").className=t?"msgscc":"Enrich";$(this.spmsgerr).innerHTML=n;document.getElementById("spmsgerr").childNodes[0].tagName=="TABLE"&&document.getElementById("spmsgerr").classList.add("container");$(this.diverrmsg).style.display=IE?"block":"table"};AGEMsg.prototype.Hide=function(){$(this.diverrmsg).style.display="none"};AGEMsg.prototype.InsertRow=function(n,t,i){var u=document.createElement("tr"),r=document.createElement("td"),f=age.createElement("DIV",r);f.innerHTML=i;r.className=t;u.appendChild(r);document.getElementById(n).appendChild(u)};AGEMsg.prototype.CheckMessageIsSucc=function(n){for(var t=0;t<n.length;t++)if(n[t]>0)return!1;return!0};AGEMsg.prototype.GenerateMessage=function(n,t,i,r){var o=!0,e,u;if(o=o&this.CheckMessageIsSucc(n),r)for(e=0;e<i.length;e++)for(ageMsg.InsertRow("tblMessage","EnrichUserName",i[e]),u=0;u<n.length;u++)n[u]<0?ageMsg.InsertRow("tblMessage","EnrichSuccmsg",t[u]):ageMsg.InsertRow("tblMessage","EnrichErrmsg",t[u]);else{var s='<table id="tblMessage" cellpadding="0" cellspacing="0" border="0" style="width:100%;">',f="";for(e=0;e<i.length;e++)for(f+='<tr><td class="EnrichUserName">',f+=i[e],f+="<\/td><\/tr>",u=0;u<n.length;u++)n[u]<0?(f+='<tr><td class="EnrichSuccmsg">',f+=t[u],f+="<\/td><\/tr>"):(f+='<tr><td class="EnrichErrmsg">',f+=t[u],f+="<\/td><\/tr>");s+=f+" <\/table>";ageMsg.ShowMsgs(s,o)}};AGEMsg.prototype.CheckMessageIsSucc2=function(n){for(var t=0;t<n.length;t++)if(n[t]>0||n[t]==-1)return!1;return!0};ageMsg=new AGEMsg;